input.content:
const fs = require('fs');
const src = fs.readFileSync(process.argv[2], 'utf8');

function grab(name) {
  const re = new RegExp('const ' + name + ' = `([\\s\\S]*?)`;');
  const m = src.match(re);
  if (!m) { console.error('NO MATCH ' + name); process.exit(1); }
  return m[1];
}

const E = grab('RAW_ELEMENTS').trim().split('\n').map(l => l.split('|'));
const R = grab('RAW_RECIPES').trim().split('\n').map(l => l.trim()).filter(Boolean);

const ids = new Set(), names = new Set(), emojis = new Map(), bad = [];
for (const p of E) {
  if (p.length < 5) { bad.push('SHORT: ' + p.join('|')); continue; }
  const [id, em, name, cat, desc] = p;
  if (ids.has(id)) bad.push('DUP ID: ' + id);
  ids.add(id);
  const nk = name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (names.has(nk)) bad.push('DUP NAME: ' + name + ' (id ' + id + ')');
  names.add(nk);
  if (emojis.has(em)) bad.push('DUP EMOJI: ' + em + ' -> ' + emojis.get(em) + ' / ' + id);
  emojis.set(em, id);
  if (!/^[a-z][a-z0-9]*$/.test(id)) bad.push('BAD ID: ' + id);
  if (!CATS_ok(cat)) bad.push('BAD CAT: ' + id + ' -> ' + cat);
  if (/[一-鿿]/.test(desc)) bad.push('CJK DESC: ' + id + ' -> ' + desc);
  if (desc.trim().length < 12) bad.push('SHORT DESC: ' + id);
}
function CATS_ok(c){return ['ia','modelo','herr','web','meto','seg','comu','marca','mix'].includes(c);}

const seenRecipe = new Map();
const missingIn = new Set(), missingOut = new Set();
const dupRecipe = [];
for (const line of R) {
  const eq = line.indexOf('=');
  if (eq < 0) { bad.push('NO EQ: ' + line); continue; }
  let key = line.slice(0, eq).trim(), res = line.slice(eq + 1).trim();
  if (!key || !res) { bad.push('EMPTY: ' + line); continue; }
  if (/[^a-z0-9_+!]/.test(key)) { bad.push('WEIRD KEY: ' + line); }
  if (/[^a-z0-9_]/.test(res)) { bad.push('WEIRD RES: ' + line); }
  const k = key.replace(/^!/, '');
  if (k.split('+').length !== 2) { bad.push('NOT PAIR: ' + line); continue; }
  const [a, b] = k.split('+');
  if (!ids.has(a)) missingIn.add(a);
  if (!ids.has(b)) missingIn.add(b);
  if (!ids.has(res)) missingOut.add(res);
  if (seenRecipe.has(k)) dupRecipe.push(k + ' -> ' + seenRecipe.get(k) + ' | ' + res);
  seenRecipe.set(k, res);
}

console.log('=== elements:', ids.size, '| recipes:', R.length);
console.log('\n=== MISSING INGREDIENTS (' + missingIn.size + ') ===');
console.log([...missingIn].sort().join(' '));
console.log('\n=== MISSING RESULTS (' + missingOut.size + ') ===');
console.log([...missingOut].sort().join(' '));
console.log('\n=== DUPLICATE RECIPE KEYS (' + dupRecipe.length + ') ===');
dupRecipe.forEach(d => console.log('  ' + d));
console.log('\n=== DATA ISSUES (' + bad.length + ') ===');
bad.forEach(b => console.log('  ' + b));

// reachability: which elements are reachable from starters
const reach = new Set(['dev','prompt','modelo','repo']);
let changed = true;
const edges = {};
for (const [k, v] of seenRecipe) { const [a,b]=k.split('+'); (edges[a] ||= []).push(v); (edges[b] ||= []).push(v); }
while (changed) { changed = false; for (const n of [...reach]) { for (const m of (edges[n]||[])) if (!reach.has(m)) { reach.add(m); changed = true; } } }
const unreachable = [...ids].filter(i => !reach.has(i));
console.log('\n=== UNREACHABLE ELEMENTS (' + unreachable.length + ') ===');
console.log(unreachable.join(' '));

const fs = require('fs');
const file = process.argv[2];
let src = fs.readFileSync(file, 'utf8');

const m = src.match(/const RAW_ELEMENTS = `([\s\S]*?)`;/);
if (!m) { console.error('no RAW_ELEMENTS'); process.exit(1); }
const block = m[1];
const lines = block.trim().split('\n').map(l => l.split('|'));

const POOL = ['🪧','🚧','🪑','🚀','⭐','🔗','🛂','🦉','🐢','🏃','🪤','🔩','🫀','🎖️','⚽','🔖','🧙','🤞','🥈','💭','📇',
'🗜️','🧷','👷','👫','🧑‍🏫','🕰️','🙋','✨','🗓️','🗡️','⚔️','🏵️','🖳️','🖇️','📔','↩️','🌿','💥','🩹','🐈‍⬛','⚙️','🚚','🛳️','🛥️','🔭','📈','🕶️',
'⛵','⛑️','🏙️','🏬','🧑‍🎨','🎛️','🗼','🗿','🪪','🗂️','🦗','🥄','🧾','🏺','🧑‍🔬','🖿','🔢','🖩️','🚩','🧱','🧺','🔒','🍫','🖧','🔄','🚂','🧑‍🍳','🎸','🌸','🗒️',
'☑️','🪢','🛍️','🛒','💳','🌍','🎒','📃','💲','⏰','📁','🥅','⏱️','🏹','🗃️','🥞','🍞','🔰','🆔','🅾️','🎴','🀄','♠️','♣️','🃏','🦋','🦚','🔱','🌒','🌝','🪶',
'🪼','🫧','🪈','🎏','🧿','🛞','🛟','🧊','🪵','🧱','🗿','🏺','🥇','🏆','🥉','🎖','📯','🧾','🗒','📰','📃','🗳','🖊','🖌','🖍','🖊','✒️','🖋','🖊'];

const usedEmoji = new Set();
const usedName = new Set();
const out = [];
const taken = new Set();

// pass 1: collect
for (const p of lines) {
  if (p.length < 5) continue;
  taken.add(p[1]);
}
// rename helper
function norm(s) { return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); }

let poolIdx = 0;
for (const p of lines) {
  if (p.length < 5) { out.push(p); continue; }
  let [id, emoji, name, cat, desc] = p;
  if (!usedEmoji.has(emoji)) {
    usedEmoji.add(emoji);
  } else {
    // find a free emoji
    let found = null;
    while (poolIdx < POOL.length) {
      const cand = POOL[poolIdx++];
      if (!taken.has(cand)) { found = cand; break; }
    }
    if (!found) { console.error('POOL EXHAUSTED for ' + id); process.exit(1); }
    taken.add(found);
    emoji = found;
    usedEmoji.add(found);
  }
  // unique names
  let nk = norm(name);
  if (usedName.has(nk)) {
    const alt = { busquedasemantica: 'Buscador semántico', semantica: 'Semántica', cache: 'Caché', caching: 'Caching', state: 'Estado de la interfaz' }[id];
    if (alt) { name = alt; nk = norm(name); }
    else {
      let i = 2; const base = name;
      while (usedName.has(nk)) { name = base + ' ' + i; nk = norm(name); i++; }
    }
    if (usedName.has(nk)) { console.error('NAME COLLISION unresolved ' + id); process.exit(1); }
  }
  usedName.add(nk);
  out.push([id, emoji, name, cat, desc].join('|'));
}

const newBlock = '\n' + out.join('\n') + '\n';
src = src.replace(m[0], 'const RAW_ELEMENTS = `' + newBlock + '`;');

// remove duplicate recipe lines with same result
const rm = src.match(/const RAW_RECIPES = `([\s\S]*?)`;/);
if (rm) {
  const rl = rm[1].trim().split('\n');
  const seen = new Map();
  const keep = [];
  for (const l of rl) {
    const k = l.trim();
    if (!k) continue;
    const norm = k.replace(/^!/, '');
    if (seen.has(norm)) continue;
    seen.set(norm, k);
    keep.push(k);
  }
  src = src.replace(rm[0], 'const RAW_RECIPES = `\n' + keep.join('\n') + '\n`;');
}

fs.writeFileSync(file, src, 'utf8');
console.log('rewrote', out.length, 'elements');

