function elByName(name){
  const n=norm(name);
  if(!n) return null;
  if(BY_NAME.has(n)) return BY_NAME.get(n);          // 1) nombre exacto
  if(EL_ID.has(n)) return EL_ID.get(n);              // 2) identificador exacto
  let best=null,score=-1;
  for(const e of ELEMENTS.values()){
    const en=norm(e.name);
    if(!en.includes(n)) continue;
    let sc = en.startsWith(n) ? 60 : 30;
    sc -= Math.min(20,en.length-n.length);
    if(sc>score){score=sc;best=e.id;}
  }
  return best;
}

